h,w=28,19
g=[[9]*w for _ in range(h)]
pts=[(2,4),(2,15),(3,4),(4,4),(6,4),(6,15),(8,4),(9,4),(10,15),(12,15),(13,4),(17,4),(18,15),(19,4),(23,4),(23,5),(23,6),(23,7),(23,11)]
for r,c in pts:g[r][c]=8
# Connect all marks on same row/column with 2, preserving marks
for r in range(h):
 cs=[c for rr,c in pts if rr==r]
 if len(cs)>1:
  for c in range(min(cs),max(cs)+1):
   if g[r][c]==9:g[r][c]=2
for c in range(w):
 rs=[r for r,cc in pts if cc==c]
 if len(rs)>1:
  for r in range(min(rs),max(rs)+1):
   if g[r][c]==9:g[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g))

# Complete the outer bounding rectangle of the 8-pixel pattern as demonstrated by the demos.
for r in range(2,24):
    if g[r][15] == 9: g[r][15]=2
for c in range(4,16):
    if g[23][c] == 9: g[23][c]=2
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
